我先核对 `Semaphore` 的接口和仓库里同类程序的写法，再按规范写出完整的 Rust 程序。```rust
use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn w1(s: Arc<Semaphore>) {
    let permit = s.acquire();
    permit.release();
}

fn w2(s: Arc<Semaphore>) {
    let permit = s.acquire();
    permit.release();
}

fn w3(s: Arc<Semaphore>) {
    let permit = s.acquire();
    permit.release();
}

fn main() {
    let s = Semaphore::new(2);

    let s1 = Arc::clone(&s);
    let h1 = thread::spawn(move || w1(s1));

    let s2 = Arc::clone(&s);
    let h2 = thread::spawn(move || w2(s2));

    let s3 = Arc::clone(&s);
    let h3 = thread::spawn(move || w3(s3));

    h1.join().unwrap();
    h2.join().unwrap();
    h3.join().unwrap();

    println!("DONE done=1");
}
